/**
 * RenDS — Data Table Organism
 * ============================
 *
 * A comprehensive, accessible data table component supporting:
 * - Sortable columns with directional indicators
 * - Row selection with multi-select and shift+click range selection
 * - Client-side pagination with configurable page size
 * - Keyboard navigation (arrow keys, Enter, Space)
 * - Column resizing via drag handle
 * - Pinned/sticky columns and headers
 * - Multiple density variants (compact, comfortable)
 * - Loading states with skeleton shimmer
 * - Empty state messaging
 * - Responsive horizontal scrolling
 * - Search/filter toolbar integration
 * - Full ARIA support for accessibility
 *
 * @example
 * <ren-table data-page-size="10">
 *   <div class="ren-table-toolbar">
 *     <input class="ren-input ren-input-sm" placeholder="Search..." data-table-search>
 *   </div>
 *   <div class="ren-table-wrapper">
 *     <table class="ren-table">
 *       <thead class="ren-table-header">
 *         <tr>
 *           <th class="ren-th ren-table-select"><input type="checkbox" aria-label="Select all"></th>
 *           <th class="ren-th ren-th-sortable" data-column="name">Name</th>
 *         </tr>
 *       </thead>
 *       <tbody class="ren-table-body">
 *         <tr class="ren-tr" data-row-id="1">
 *           <td class="ren-td ren-table-select"><input type="checkbox" aria-label="Select row"></td>
 *           <td class="ren-td">John Doe</td>
 *         </tr>
 *       </tbody>
 *     </table>
 *   </div>
 *   <div class="ren-table-pagination"></div>
 * </ren-table>
 */

/* ===== Base Table Structure ===== */

ren-table {
  container-type: inline-size;
  container-name: ren-table;
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

.ren-table-wrapper {
  flex: 1;
  overflow-x: auto;
  overflow-y: auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;

  &::-webkit-scrollbar {
    height: 8px;
    width: 8px;
  }

  &::-webkit-scrollbar-track {
    background: transparent;
  }

  &::-webkit-scrollbar-thumb {
    background-color: var(--color-border);
    border-radius: var(--radius-sm);
    transition: background-color var(--duration-state) var(--ease-enter);

    &:hover {
      background-color: var(--color-text-muted);
    }
  }
}

.ren-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--color-surface);
  font-size: var(--body-size);
  color: var(--color-text);
}

/* ===== Header Styles ===== */

.ren-table-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background-color: var(--color-surface-raised);
}

.ren-table-header tr {
  border-bottom: 1px solid var(--color-border);
}

.ren-th {
  padding: var(--space-3) var(--space-4);
  text-align: start;
  font-weight: var(--label-weight);
  font-size: var(--label-size);
  color: var(--color-text);
  user-select: none;
  white-space: nowrap;
  background-color: var(--color-surface-raised);
  border-inline-end: 1px solid var(--color-border);
  height: 44px;
  display: table-cell;
  vertical-align: middle;

  &:last-child {
    border-inline-end: none;
  }

  &:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }
}

.ren-th-sortable {
  cursor: pointer;
  position: relative;
  transition: background-color var(--duration-tactile) var(--ease-enter);

  &:hover {
    background-color: var(--color-fill);
  }

  &::after {
    content: '';
    display: inline-block;
    width: 12px;
    height: 12px;
    margin-inline-start: var(--space-2);
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 12" fill="none"><path d="M3 8L6 5l3 3M3 4L6 7l3-3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>');
    background-size: contain;
    background-repeat: no-repeat;
    opacity: 0.4;
    transition: opacity var(--duration-tactile) var(--ease-enter), transform var(--duration-tactile) var(--ease-enter);
    vertical-align: middle;
    color: var(--color-text-muted);
  }

  &[data-sort="asc"]::after {
    opacity: 1;
    transform: scaleY(1);
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 12" fill="none"><path d="M6 2v6M3 5l3-3 3 3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>');
  }

  &[data-sort="desc"]::after {
    opacity: 1;
    transform: scaleY(-1);
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 12" fill="none"><path d="M6 2v6M3 5l3-3 3 3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>');
  }
}

.ren-th-resize {
  position: absolute;
  inset-inline-end: 0;
  top: 0;
  height: 100%;
  width: 4px;
  cursor: col-resize;
  user-select: none;
  background-color: transparent;
  padding: 0;
  margin: 0;
  transition: background-color var(--duration-tactile) var(--ease-enter);

  &:hover,
  &:active {
    background-color: var(--color-accent);
  }
}

/* Pinned columns */
.ren-th-pinned {
  position: sticky;
  z-index: 11;
}

/* ===== Body & Row Styles ===== */

.ren-table-body {
  background-color: var(--color-surface);
}

.ren-tr {
  border-bottom: var(--stroke-1) solid var(--color-border);
  transition: background-color var(--duration-tactile) var(--ease-enter);
  height: 44px;

  &:nth-child(even) {
    background-color: var(--color-fill);
  }

  &:hover {
    background-color: var(--color-fill-hover);
  }

  &[aria-selected="true"] {
    background-color: var(--color-accent-subtle);

    .ren-td {
      background-color: var(--color-accent-subtle);
    }
  }

  &:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: -1px;
  }
}

.ren-td {
  padding: var(--space-3) var(--space-4);
  border-inline-end: 1px solid var(--color-border);
  color: var(--color-text);
  vertical-align: middle;
  height: 44px;

  &:last-child {
    border-inline-end: none;
  }

  &:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }
}

/* Pinned column cells */
.ren-td-pinned {
  position: sticky;
  z-index: 9;
  background-color: inherit;
}

/* ===== Selection Styles ===== */

.ren-table-select {
  width: var(--space-10);
  padding: var(--space-3);
  text-align: center;

  input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
    accent-color: var(--color-accent);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    transition: background-color var(--duration-tactile) var(--ease-enter),
                border-color var(--duration-tactile) var(--ease-enter);

    &:hover:not(:disabled) {
      border-color: var(--color-accent);
    }

    &:checked {
      background-color: var(--color-accent);
      border-color: var(--color-accent);
      color: var(--color-on-accent);
    }

    &:focus-visible {
      outline: 2px solid var(--color-accent);
      outline-offset: 2px;
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
}

/* ===== Pagination ===== */

.ren-table-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--color-border);
  background-color: var(--color-surface);
  font-size: var(--caption-size);
  color: var(--color-text-muted);
  gap: var(--space-4);

  &:empty {
    display: none;
  }
}

.ren-table-pagination-info {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--body-size);
  color: var(--color-text);
}

.ren-table-pagination-controls {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.ren-table-pagination-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--touch-min);
  height: var(--touch-min);
  padding: var(--space-2);
  background-color: var(--color-fill);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  font-size: var(--body-size);
  cursor: pointer;
  transition: background-color var(--duration-tactile) var(--ease-enter),
              border-color var(--duration-tactile) var(--ease-enter);
  user-select: none;
  min-width: 44px;
  min-height: 44px;

  &:hover:not(:disabled) {
    background-color: var(--color-fill-hover);
    border-color: var(--color-accent);
  }

  &:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    background-color: var(--color-fill);
  }
}

/* ===== Toolbar Styles ===== */

.ren-table-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background-color: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  flex-wrap: wrap;

  &:empty {
    display: none;
  }
}

.ren-table-toolbar-search {
  flex: 1;
  min-width: 200px;
  max-width: 300px;
}

/* ===== Empty State ===== */

.ren-table-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-10);
  gap: var(--space-4);
  text-align: center;
  color: var(--color-text-muted);
  background-color: var(--color-surface);
  min-height: 200px;

  .ren-table-empty-icon {
    font-size: 40px;
    opacity: 0.4;
  }

  .ren-table-empty-title {
    font-size: var(--label-size);
    font-weight: var(--label-weight);
    color: var(--color-text);
  }

  .ren-table-empty-description {
    font-size: var(--caption-size);
    color: var(--color-text-muted);
    max-width: 300px;
  }
}

/* ===== Loading State ===== */

ren-table[data-loading] {
  .ren-table-body {
    position: relative;
  }

  .ren-tr {
    opacity: 0.5;
    pointer-events: none;
  }
}

.ren-table-loading-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent,
    rgb(255, 255, 255, 0.4),
    transparent
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
  z-index: 20;
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }

  100% {
    background-position: 200% 0;
  }
}

/* ===== Density Variants ===== */

.ren-table-compact {
  .ren-th,
  .ren-td {
    padding: var(--space-2) var(--space-3);
    height: 32px;
  }

  .ren-tr {
    height: 32px;
  }
}

.ren-table-comfortable {
  .ren-th,
  .ren-td {
    padding: var(--space-4) var(--space-5);
    height: 56px;
  }

  .ren-tr {
    height: 56px;
  }
}

/* ===== Responsive Design (Container Query) ===== */

@container ren-table (max-width: 600px) {
  .ren-table {
    min-width: 600px;
  }

  .ren-table-pagination {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-3);
  }

  .ren-table-pagination-info {
    width: 100%;
  }

  .ren-table-pagination-controls {
    width: 100%;
    justify-content: space-between;
  }

  .ren-table-toolbar {
    flex-direction: column;
  }

  .ren-table-toolbar-search {
    min-width: 100%;
    max-width: 100%;
  }
}

/* ===== Accessibility ===== */

/* High contrast mode support */
@media (prefers-contrast: more) {
  .ren-th {
    border: 1px solid var(--color-text);
  }

  .ren-td {
    border: var(--stroke-1) solid var(--color-text);
  }

  .ren-th-sortable:hover {
    background-color: var(--color-text);
    color: var(--color-surface);
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  .ren-tr,
  .ren-th-sortable,
  .ren-table-pagination-button,
  .ren-table-select input[type="checkbox"] {
    transition: none;
  }

  .ren-table-loading-overlay {
    animation: none;
    background: rgb(255, 255, 255, 0.2);
  }
}

/* Dark mode support (if light/dark theming is used) */
@media (prefers-color-scheme: dark) {
  .ren-table {
    /* Uses CSS custom properties from design tokens */
    /* No additional overrides needed if tokens are properly defined */
  }
}
/* Appearance API bridge */
.ren-table { font-size: var(--ren-table-header-size, var(--body-size)); }
.ren-table thead { background: var(--ren-table-header-bg, var(--color-surface-sunken)); color: var(--ren-table-header-color, var(--color-text-muted)); font-weight: var(--ren-table-header-weight, var(--weight-semibold)); }
.ren-table tr { min-block-size: var(--ren-table-row-height, var(--size-lg)); block-size: var(--ren-table-row-height, var(--size-lg)); }
.ren-table th, .ren-table td { padding: var(--ren-table-cell-padding, var(--space-3)); }
.ren-table { border-color: var(--ren-table-border-color, var(--color-border-muted)); }
.ren-table tbody tr:nth-child(even) { background: var(--ren-table-stripe-bg, var(--color-surface-sunken)); }
.ren-table tbody tr:hover { background: var(--ren-table-hover-bg, var(--color-fill)); }
.ren-table tbody tr[aria-selected="true"], .ren-table tbody tr[data-selected] { background: var(--ren-table-selected-bg, var(--color-accent-subtle)); }


/**
 * RenDS — Data Table Organism
 * ============================
 *
 * A comprehensive, accessible data table web component that extends native
 * HTML tables with powerful features while maintaining semantic structure.
 *
 * Features:
 * - Click-to-sort columns with asc/desc/none cycling
 * - Multi-select with select-all checkbox and shift+click range selection
 * - Client-side pagination with configurable page size
 * - Keyboard navigation (arrow keys, Enter to sort, Space to select)
 * - Client-side filtering/search
 * - Column resizing via drag handle
 * - Pinned/sticky column support
 * - Multiple density variants (compact, comfortable, default)
 * - Loading state with shimmer effect
 * - Empty state messaging
 * - Full ARIA support for accessibility
 * - Light DOM (no Shadow DOM) for easy styling and integration
 *
 * @example
 * <ren-table data-page-size="10">
 *   <div class="ren-table-wrapper">
 *     <table class="ren-table">
 *       <thead class="ren-table-header">
 *         <tr>
 *           <th class="ren-th ren-table-select"><input type="checkbox"></th>
 *           <th class="ren-th ren-th-sortable" data-column="name">Name</th>
 *         </tr>
 *       </thead>
 *       <tbody class="ren-table-body">
 *         <tr class="ren-tr" data-row-id="1">
 *           <td class="ren-td ren-table-select"><input type="checkbox"></td>
 *           <td class="ren-td">John Doe</td>
 *         </tr>
 *       </tbody>
 *     </table>
 *   </div>
 *   <div class="ren-table-pagination"></div>
 * </ren-table>
 *
 * @fires ren-sort - Dispatched when column sort changes: { column, direction }
 * @fires ren-select - Dispatched when row selection changes: { selected }
 * @fires ren-page - Dispatched when page changes: { page, pageSize }
 * @fires ren-filter - Dispatched when filter changes: { columnIndex, value }
 */

export class RenTable extends HTMLElement {
  #table = null;
  #thead = null;
  #tbody = null;
  #headerCheckbox = null;
  #rowCheckboxes = [];
  #headerCells = [];
  #rows = [];
  #visibleRows = [];
  #sortColumn = null;
  #sortDirection = null;
  #selectedRows = new Set();
  #currentPage = 1;
  #pageSize = 10;
  #filterValues = new Map();
  #columnWidths = new Map();
  #resizingColumn = null;
  #resizeStartX = 0;
  #resizeStartWidth = 0;
  #lastSelectedRowIndex = -1;
  #listenerController = null;
  #rowCheckboxController = null;

  constructor() {
    super();
  }

  connectedCallback() {
    this._initializeComponent();
    this._attachEventListeners();
    this._setupPagination();
  }

  disconnectedCallback() {
    this._removeEventListeners();
  }

  /**
   * Initialize table references and attributes
   * @private
   */
  _initializeComponent() {
    this.#table = this.querySelector('.ren-table');
    this.#thead = this.querySelector('.ren-table-header');
    this.#tbody = this.querySelector('.ren-table-body');

    if (!this.#table || !this.#thead || !this.#tbody) {
      console.warn('RenTable: Missing required table structure');
      return;
    }

    // Get page size from attribute
    const pageSize = this.getAttribute('data-page-size');
    if (pageSize) {
      this.#pageSize = parseInt(pageSize, 10);
    }

    // Initialize header cells
    this.#headerCells = Array.from(this.#thead.querySelectorAll('.ren-th'));
    this.#headerCheckbox = this.#thead.querySelector('input[type="checkbox"]');

    // Initialize rows
    this._refreshRows();

    // Add ARIA roles
    this.#table.setAttribute('role', 'table');
    if (!this.#thead.hasAttribute('role')) {
      this.#thead.setAttribute('role', 'rowgroup');
    }
    if (!this.#tbody.hasAttribute('role')) {
      this.#tbody.setAttribute('role', 'rowgroup');
    }
  }

  /**
   * Attach all event listeners
   * @private
   */
  _attachEventListeners() {
    this.#listenerController?.abort();
    this.#listenerController = new AbortController();
    const { signal } = this.#listenerController;

    // Sorting
    this.#headerCells.forEach((cell, index) => {
      if (cell.classList.contains('ren-th-sortable')) {
        cell.addEventListener('click', () => this._handleSort(cell, index), { signal });
        cell.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            this._handleSort(cell, index);
          }
        }, { signal });
        cell.setAttribute('tabindex', '0');
        cell.setAttribute('role', 'columnheader');
        cell.setAttribute('aria-sort', 'none');
      }
    });

    // Selection - header checkbox
    if (this.#headerCheckbox) {
      this.#headerCheckbox.addEventListener('change', () => this._handleSelectAll(), { signal });
    }

    // Selection - row checkboxes
    this._attachRowCheckboxListeners();

    // Keyboard navigation
    this.#table.addEventListener('keydown', (e) => this._handleKeyboard(e), { signal });

    // Column resizing
    this._setupColumnResize(signal);

    // Search input
    const searchInput = this.querySelector('[data-table-search]');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        this._filterRows(e.target.value);
      }, { signal });
    }

    // Pagination button clicks
    const paginationCtrls = this.querySelector('.ren-table-pagination-controls');
    if (paginationCtrls) {
      const prevBtn = paginationCtrls.querySelector('[data-page-prev]');
      const nextBtn = paginationCtrls.querySelector('[data-page-next]');

      if (prevBtn) prevBtn.addEventListener('click', () => this._previousPage(), { signal });
      if (nextBtn) nextBtn.addEventListener('click', () => this._nextPage(), { signal });
    }

    // Pagination page size selector
    const pageSizeSelect = this.querySelector('[data-page-size-select]');
    if (pageSizeSelect) {
      pageSizeSelect.addEventListener('change', (e) => {
        this.#pageSize = parseInt(e.target.value, 10);
        this.#currentPage = 1;
        this._renderTable();
      }, { signal });
    }
  }

  /**
   * Remove event listeners
   * @private
   */
  _removeEventListeners() {
    this.#listenerController?.abort();
    this.#listenerController = null;
    this.#rowCheckboxController?.abort();
    this.#rowCheckboxController = null;
    this.#resizingColumn = null;
  }

  /**
   * Refresh the list of all rows
   * @private
   */
  _refreshRows() {
    this.#rows = Array.from(this.#tbody.querySelectorAll('.ren-tr'));
    this.#visibleRows = [...this.#rows];
    this._attachRowCheckboxListeners();
  }

  /**
   * Attach listeners to row checkboxes
   * @private
   */
  _attachRowCheckboxListeners() {
    this.#rowCheckboxController?.abort();
    this.#rowCheckboxController = new AbortController();
    const { signal } = this.#rowCheckboxController;

    const checkboxes = Array.from(this.#tbody.querySelectorAll('.ren-table-select input[type="checkbox"]'));
    checkboxes.forEach((checkbox, index) => {
      checkbox.addEventListener('change', (e) => {
        this._handleRowSelect(e, index);
      }, { signal });
    });
    this.#rowCheckboxes = checkboxes;
  }

  /**
   * Handle column header click for sorting
   * @private
   */
  _handleSort(cell, index) {
    const columnName = cell.getAttribute('data-column');
    if (!columnName) return;

    // Cycle through sort states: none -> asc -> desc -> none
    let newDirection = null;
    if (this.#sortColumn !== columnName) {
      newDirection = 'asc';
    } else if (this.#sortDirection === 'asc') {
      newDirection = 'desc';
    } else if (this.#sortDirection === 'desc') {
      newDirection = null;
    } else {
      newDirection = 'asc';
    }

    this.#sortColumn = newDirection ? columnName : null;
    this.#sortDirection = newDirection;

    // Update visual indicators
    this.#headerCells.forEach((hc) => {
      if (hc.classList.contains('ren-th-sortable')) {
        hc.removeAttribute('data-sort');
        hc.setAttribute('aria-sort', 'none');
      }
    });

    if (newDirection) {
      cell.setAttribute('data-sort', newDirection);
      cell.setAttribute('aria-sort', newDirection === 'asc' ? 'ascending' : 'descending');
    }

    // Dispatch event
    this._dispatchEvent('ren-sort', {
      column: columnName,
      direction: newDirection,
    });

    // Re-render
    this.#currentPage = 1;
    this._renderTable();
  }

  /**
   * Handle select all checkbox
   * @private
   */
  _handleSelectAll() {
    const isChecked = this.#headerCheckbox.checked;

    this.#visibleRows.forEach((row) => {
      const rowId = row.getAttribute('data-row-id');
      const checkbox = row.querySelector('input[type="checkbox"]');

      if (isChecked) {
        this.#selectedRows.add(rowId);
        row.setAttribute('aria-selected', 'true');
        if (checkbox) checkbox.checked = true;
      } else {
        this.#selectedRows.delete(rowId);
        row.removeAttribute('aria-selected');
        if (checkbox) checkbox.checked = false;
      }
    });

    this._dispatchEvent('ren-select', {
      selected: Array.from(this.#selectedRows),
    });
  }

  /**
   * Handle individual row selection
   * @private
   */
  _handleRowSelect(event, rowIndex) {
    const row = this.#visibleRows[rowIndex];
    if (!row) return;

    const rowId = row.getAttribute('data-row-id');
    const isChecked = event.target.checked;
    const isShiftClick = event.shiftKey;

    if (isShiftClick && this.#lastSelectedRowIndex !== -1) {
      // Range selection
      const start = Math.min(this.#lastSelectedRowIndex, rowIndex);
      const end = Math.max(this.#lastSelectedRowIndex, rowIndex);

      for (let i = start; i <= end; i++) {
        const rangeRow = this.#visibleRows[i];
        const rangeRowId = rangeRow.getAttribute('data-row-id');
        const rangeCheckbox = rangeRow.querySelector('input[type="checkbox"]');

        if (isChecked) {
          this.#selectedRows.add(rangeRowId);
          rangeRow.setAttribute('aria-selected', 'true');
          if (rangeCheckbox) rangeCheckbox.checked = true;
        } else {
          this.#selectedRows.delete(rangeRowId);
          rangeRow.removeAttribute('aria-selected');
          if (rangeCheckbox) rangeCheckbox.checked = false;
        }
      }
    } else {
      // Single selection
      if (isChecked) {
        this.#selectedRows.add(rowId);
        row.setAttribute('aria-selected', 'true');
      } else {
        this.#selectedRows.delete(rowId);
        row.removeAttribute('aria-selected');
      }
    }

    this.#lastSelectedRowIndex = rowIndex;

    // Update select-all checkbox state
    this._updateSelectAllCheckbox();

    // Dispatch event
    this._dispatchEvent('ren-select', {
      selected: Array.from(this.#selectedRows),
    });
  }

  /**
   * Update select-all checkbox based on row selections
   * @private
   */
  _updateSelectAllCheckbox() {
    if (!this.#headerCheckbox) return;

    const visibleRowIds = this.#visibleRows
      .map((row) => row.getAttribute('data-row-id'))
      .filter(Boolean);
    const allVisibleSelected = visibleRowIds.every((id) =>
      this.#selectedRows.has(id)
    );
    const someSelected = visibleRowIds.some((id) =>
      this.#selectedRows.has(id)
    );

    this.#headerCheckbox.checked = allVisibleSelected;
    this.#headerCheckbox.indeterminate = someSelected && !allVisibleSelected;
  }

  /**
   * Handle keyboard navigation
   * @private
   */
  _handleKeyboard(event) {
    const { key, target } = event;

    // Space to toggle row selection
    if (key === ' ' && target.classList.contains('ren-tr')) {
      event.preventDefault();
      const checkbox = target.querySelector('input[type="checkbox"]');
      if (checkbox) {
        checkbox.checked = !checkbox.checked;
        checkbox.dispatchEvent(new Event('change', { bubbles: true }));
      }
    }

    // Arrow keys for navigation
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      event.preventDefault();
      this._navigateCells(target, key);
    }

    // Enter to sort (on header)
    if (key === 'Enter' && target.classList.contains('ren-th-sortable')) {
      event.preventDefault();
      target.click();
    }
  }

  /**
   * Navigate between cells with arrow keys
   * @private
   */
  _navigateCells(currentCell, direction) {
    let nextCell = currentCell;

    if (direction === 'ArrowUp') {
      const row = currentCell.closest('tr');
      const prevRow = row?.previousElementSibling;
      if (prevRow) {
        const cellIndex = Array.from(row.cells).indexOf(currentCell);
        nextCell = prevRow.cells[cellIndex];
      }
    } else if (direction === 'ArrowDown') {
      const row = currentCell.closest('tr');
      const nextRow = row?.nextElementSibling;
      if (nextRow) {
        const cellIndex = Array.from(row.cells).indexOf(currentCell);
        nextCell = nextRow.cells[cellIndex];
      }
    } else if (direction === 'ArrowLeft') {
      nextCell = currentCell.previousElementSibling || currentCell;
    } else if (direction === 'ArrowRight') {
      nextCell = currentCell.nextElementSibling || currentCell;
    }

    if (nextCell && nextCell !== currentCell) {
      nextCell.focus();
    }
  }

  /**
   * Setup column resizing
   * @private
   */
  _setupColumnResize(signal) {
    this.#headerCells.forEach((cell) => {
      let resizeHandle = cell.querySelector('.ren-th-resize');

      if (!resizeHandle) {
        resizeHandle = document.createElement('div');
        resizeHandle.className = 'ren-th-resize';
        cell.appendChild(resizeHandle);
      }

      resizeHandle.addEventListener('mousedown', (e) => {
        this._startResize(e, cell);
      }, { signal });
    });

    document.addEventListener('mousemove', (e) => this._handleResize(e), { signal });
    document.addEventListener('mouseup', () => this._endResize(), { signal });
  }

  /**
   * Start column resize
   * @private
   */
  _startResize(event, cell) {
    this.#resizingColumn = cell;
    this.#resizeStartX = event.clientX;
    this.#resizeStartWidth = cell.offsetWidth;
    cell.style.cursor = 'col-resize';
  }

  /**
   * Handle column resize drag
   * @private
   */
  _handleResize(event) {
    if (!this.#resizingColumn) return;

    const delta = event.clientX - this.#resizeStartX;
    const newWidth = Math.max(80, this.#resizeStartWidth + delta);
    this.#resizingColumn.style.width = `${newWidth}px`;
  }

  /**
   * End column resize
   * @private
   */
  _endResize() {
    if (this.#resizingColumn) {
      this.#resizingColumn.style.cursor = '';
      this.#resizingColumn = null;
    }
  }

  /**
   * Filter rows by search value
   * @private
   */
  _filterRows(searchValue) {
    const lowerSearch = searchValue.toLowerCase();

    this.#visibleRows = this.#rows.filter((row) => {
      const cells = Array.from(row.querySelectorAll('.ren-td'));
      return cells.some((cell) =>
        cell.textContent.toLowerCase().includes(lowerSearch)
      );
    });

    this.#currentPage = 1;
    this._renderTable();

    this._dispatchEvent('ren-filter', {
      value: searchValue,
    });
  }

  /**
   * Sort visible rows
   * @private
   */
  _sortVisibleRows() {
    if (!this.#sortColumn || !this.#sortDirection) return;

    const columnIndex = this.#headerCells.findIndex(
      (cell) => cell.getAttribute('data-column') === this.#sortColumn
    );

    if (columnIndex === -1) return;

    this.#visibleRows.sort((a, b) => {
      const aValue = a.cells[columnIndex]?.textContent || '';
      const bValue = b.cells[columnIndex]?.textContent || '';

      // Try numeric comparison first
      const aNum = parseFloat(aValue);
      const bNum = parseFloat(bValue);

      let comparison = 0;
      if (!isNaN(aNum) && !isNaN(bNum)) {
        comparison = aNum - bNum;
      } else {
        comparison = aValue.localeCompare(bValue);
      }

      return this.#sortDirection === 'asc' ? comparison : -comparison;
    });
  }

  /**
   * Setup pagination controls
   * @private
   */
  _setupPagination() {
    const paginationDiv = this.querySelector('.ren-table-pagination');
    if (!paginationDiv) return;

    // Only render pagination if there are rows
    if (this.#visibleRows.length === 0) {
      paginationDiv.innerHTML = '';
      return;
    }

    const totalPages = Math.ceil(this.#visibleRows.length / this.#pageSize);
    if (totalPages <= 1) {
      paginationDiv.innerHTML = '';
      return;
    }

    const startItem = (this.#currentPage - 1) * this.#pageSize + 1;
    const endItem = Math.min(this.#currentPage * this.#pageSize, this.#visibleRows.length);

    paginationDiv.innerHTML = `
      <div class="ren-table-pagination-info">
        <span>Showing <strong>${startItem}</strong> to <strong>${endItem}</strong> of <strong>${this.#visibleRows.length}</strong></span>
      </div>
      <div class="ren-table-pagination-controls">
        <button class="ren-table-pagination-button" data-page-prev aria-label="Previous page" ${this.#currentPage === 1 ? 'disabled' : ''}>
          ← Prev
        </button>
        <span style="padding: 0 var(--space-2); font-size: var(--caption-size); color: var(--color-text-muted);">
          Page ${this.#currentPage} of ${totalPages}
        </span>
        <button class="ren-table-pagination-button" data-page-next aria-label="Next page" ${this.#currentPage === totalPages ? 'disabled' : ''}>
          Next →
        </button>
      </div>
    `;

    // Reattach listeners
    const prevBtn = paginationDiv.querySelector('[data-page-prev]');
    const nextBtn = paginationDiv.querySelector('[data-page-next]');
    const listenerOptions = this.#listenerController
      ? { signal: this.#listenerController.signal }
      : undefined;

    if (prevBtn) prevBtn.addEventListener('click', () => this._previousPage(), listenerOptions);
    if (nextBtn) nextBtn.addEventListener('click', () => this._nextPage(), listenerOptions);
  }

  /**
   * Go to previous page
   * @private
   */
  _previousPage() {
    if (this.#currentPage > 1) {
      this.#currentPage--;
      this._renderTable();
    }
  }

  /**
   * Go to next page
   * @private
   */
  _nextPage() {
    const totalPages = Math.ceil(this.#visibleRows.length / this.#pageSize);
    if (this.#currentPage < totalPages) {
      this.#currentPage++;
      this._renderTable();
    }
  }

  /**
   * Render the table with current page, sort, and filter
   * @private
   */
  _renderTable() {
    // Apply sorting
    this._sortVisibleRows();

    // Show/hide rows based on current page
    const startIndex = (this.#currentPage - 1) * this.#pageSize;
    const endIndex = startIndex + this.#pageSize;

    const visibleIndexByRow = new Map(
      this.#visibleRows.map((row, visibleIndex) => [row, visibleIndex])
    );

    this.#rows.forEach((row) => {
      const visibleIndex = visibleIndexByRow.get(row);
      const isVisible = visibleIndex !== undefined &&
        visibleIndex >= startIndex &&
        visibleIndex < endIndex;

      if (isVisible) {
        row.style.display = '';
        row.setAttribute('role', 'row');
      } else {
        row.style.display = 'none';
      }
    });

    // Update pagination
    this._setupPagination();

    // Show/hide empty state
    this._updateEmptyState();
  }

  /**
   * Update empty state display
   * @private
   */
  _updateEmptyState() {
    let emptyState = this.querySelector('.ren-table-empty');

    if (this.#visibleRows.length === 0) {
      if (!emptyState) {
        emptyState = document.createElement('div');
        emptyState.className = 'ren-table-empty';
        emptyState.innerHTML = `
          <div class="ren-table-empty-icon">📭</div>
          <div class="ren-table-empty-title">No results</div>
          <div class="ren-table-empty-description">No data matches your search or filters</div>
        `;
        const wrapper = this.querySelector('.ren-table-wrapper');
        if (wrapper) {
          wrapper.parentNode.insertBefore(emptyState, wrapper);
        }
      }
      if (this.#tbody) {
        this.#tbody.style.display = 'none';
      }
    } else {
      if (emptyState) {
        emptyState.remove();
      }
      if (this.#tbody) {
        this.#tbody.style.display = '';
      }
    }
  }

  /**
   * Dispatch custom event
   * @private
   */
  _dispatchEvent(eventName, detail) {
    this.dispatchEvent(
      new CustomEvent(eventName, {
        detail,
        bubbles: true,
        composed: true,
      })
    );
  }

  /**
   * Public API: Filter rows by column
   * @param {number} columnIndex - Index of column to filter
   * @param {string} value - Filter value
   */
  filter(columnIndex, value) {
    this.#filterValues.set(columnIndex, value);

    this.#visibleRows = this.#rows.filter((row) => {
      for (const [colIdx, filterVal] of this.#filterValues) {
        const cell = row.cells[colIdx];
        if (!cell || !cell.textContent.toLowerCase().includes(filterVal.toLowerCase())) {
          return false;
        }
      }
      return true;
    });

    this.#currentPage = 1;
    this._renderTable();
  }

  /**
   * Public API: Get selected row IDs
   * @returns {string[]} Array of selected row IDs
   */
  getSelectedRows() {
    return Array.from(this.#selectedRows);
  }

  /**
   * Public API: Set loading state
   * @param {boolean} isLoading - Whether table is loading
   */
  setLoading(isLoading) {
    if (isLoading) {
      this.setAttribute('data-loading', '');
      const wrapper = this.querySelector('.ren-table-wrapper');
      if (wrapper && !wrapper.querySelector('.ren-table-loading-overlay')) {
        const overlay = document.createElement('div');
        overlay.className = 'ren-table-loading-overlay';
        wrapper.appendChild(overlay);
      }
    } else {
      this.removeAttribute('data-loading');
      const overlay = this.querySelector('.ren-table-loading-overlay');
      if (overlay) overlay.remove();
    }
  }

  /**
   * Public API: Set density variant
   * @param {'default' | 'compact' | 'comfortable'} density - Density variant
   */
  setDensity(density) {
    this.#table.classList.remove('ren-table-compact', 'ren-table-comfortable');
    if (density === 'compact' || density === 'comfortable') {
      this.#table.classList.add(`ren-table-${density}`);
    }
  }

  /**
   * Public API: Clear all selections
   */
  clearSelection() {
    this.#selectedRows.clear();
    this.#rowCheckboxes.forEach((checkbox) => {
      checkbox.checked = false;
    });
    if (this.#headerCheckbox) {
      this.#headerCheckbox.checked = false;
      this.#headerCheckbox.indeterminate = false;
    }
    this.#rows.forEach((row) => {
      row.removeAttribute('aria-selected');
    });
    this._dispatchEvent('ren-select', { selected: [] });
  }

  /**
   * Public API: Refresh table data
   */
  refresh() {
    this._refreshRows();
    this.#currentPage = 1;
    this._renderTable();
  }
}

customElements.define('ren-table', RenTable);

# ren-avatar Component Contract

User identity primitive for images, initials, and presence indicators.

Load this file after `ren-design.md` and before generating, editing, or reviewing `ren-avatar` UI.

## Purpose

- Provide the agent-facing public contract for the `ren-avatar` primitive.
- Keep generated markup aligned with the colocated CSS/JS source.
- Route theming through semantic tokens and the component token API instead of ad hoc styles.

## Use When

- You need the Avatar primitive behavior or visual role.
- The UI should stay inside RenDS' vanilla HTML/CSS/JS conventions.
- The implementation can use the public selectors, states, and imports listed here.

## Do Not Use When

- Native HTML plus `base/primitive-zero.md` is enough.
- A simpler primitive can express the UI without this primitive.
- You would need to invent undocumented selectors, states, or JavaScript APIs.

