/* ═══ REN SLIDER WEB COMPONENT ═══ */

export class RenSlider extends HTMLElement {
  constructor() {
    super();
    this.handleInput = this.handleInput.bind(this);
    this.handleChange = this.handleChange.bind(this);
    this.handleRangePointerDown = this.handleRangePointerDown.bind(this);
    this.handleRangePointerMove = this.handleRangePointerMove.bind(this);
    this.handleRangePointerEnd = this.handleRangePointerEnd.bind(this);
  }

  connectedCallback() {
    this.inputs = [...this.querySelectorAll('input[type="range"]')];
    this.input = this.inputs[0] || null;

    if (!this.input) {
      console.warn('RenSlider: No input[type="range"] found');
      return;
    }

    /* ═══ SET UP TRACK CLASS ═══ */
    const trackContainer = this.input.parentElement || this.input;
    trackContainer.classList.add('ren-slider-track');

    /* ═══ INITIALIZE VALUE ═══ */
    this.updateValue();

    /* ═══ EVENT LISTENERS ═══ */
    this.inputs.forEach((input) => {
      input.addEventListener('input', this.handleInput);
      input.addEventListener('change', this.handleChange);
    });

    this.range = this.inputs.length === 2 ? this.querySelector('.ren-slider-range') : null;
    this.range?.addEventListener('pointerdown', this.handleRangePointerDown, true);
    this.range?.addEventListener('pointermove', this.handleRangePointerMove, true);
    this.range?.addEventListener('pointerup', this.handleRangePointerEnd, true);
    this.range?.addEventListener('pointercancel', this.handleRangePointerEnd, true);

    /* ═══ HANDLE LABEL DISPLAY ═══ */
    const label = this.getAttribute('label');
    if (label && !this.querySelector('.ren-slider-label')) {
      const labelEl = document.createElement('div');
      labelEl.className = 'ren-slider-label';
      labelEl.textContent = label;
      this.insertBefore(labelEl, this.input.parentElement);
    }

    /* ═══ HANDLE VALUE DISPLAY ═══ */
    if (this.hasAttribute('show-value')) {
      this.valueDisplay = this.querySelector('.ren-slider-value');
      if (!this.valueDisplay) {
        const valueEl = document.createElement('div');
        valueEl.className = 'ren-slider-value';
        this.valueDisplay = valueEl;
        this.input.parentElement.appendChild(valueEl);
      }
      this.updateValueDisplay();
    }

    /* ═══ TRANSFER VARIANT CLASSES ═══ */
    this.transferVariantClasses();
  }

  disconnectedCallback() {
    this.inputs?.forEach((input) => {
      input.removeEventListener('input', this.handleInput);
      input.removeEventListener('change', this.handleChange);
    });
    this.range?.removeEventListener('pointerdown', this.handleRangePointerDown, true);
    this.range?.removeEventListener('pointermove', this.handleRangePointerMove, true);
    this.range?.removeEventListener('pointerup', this.handleRangePointerEnd, true);
    this.range?.removeEventListener('pointercancel', this.handleRangePointerEnd, true);
    this.pointerDrag = null;
  }

  /* ═══ UPDATE CSS VARIABLE FOR TRACK FILL ═══ */
  updateValue() {
    if (!this.input) return;

    const percentages = this.inputs.map((input) => {
      const min = Number(input.min || 0);
      const max = Number(input.max || 100);
      const value = input.valueAsNumber;
      const percentage = ((value - min) / (max - min)) * 100;
      input.style.setProperty('--value', `${percentage}%`);
      return percentage;
    });

    if (percentages.length === 2) {
      const track = this.querySelector('.ren-slider-track-input');
      track?.style.setProperty('--value-start', `${Math.min(...percentages)}%`);
      track?.style.setProperty('--value-end', `${Math.max(...percentages)}%`);
    }
  }

  /* ═══ UPDATE VALUE DISPLAY TEXT ═══ */
  updateValueDisplay() {
    if (!this.valueDisplay || !this.input) return;

    const value = this.inputs.length === 2
      ? this.inputs.map((input) => input.value).join(' – ')
      : this.input.value;
    const unit = this.getAttribute('unit') || '';
    this.valueDisplay.textContent = `${value}${unit}`;
  }

  /* ═══ INPUT EVENT HANDLER ═══ */
  handleInput(event) {
    if (this.inputs.length === 2) {
      const [lower, upper] = this.inputs;
      if (event.target === lower && lower.valueAsNumber > upper.valueAsNumber) {
        lower.value = upper.value;
      } else if (event.target === upper && upper.valueAsNumber < lower.valueAsNumber) {
        upper.value = lower.value;
      }
    }
    this.updateValue();
    this.updateValueDisplay();

    this.dispatchEvent(
      new CustomEvent('ren-slider-input', {
        detail: { value: this.value },
        bubbles: true,
        composed: true,
      })
    );
  }

  isVerticalRange() {
    return this.classList.contains('ren-slider-vertical');
  }

  pointerPosition(event) {
    return this.isVerticalRange() ? -event.clientY : event.clientX;
  }

  valueFromPointer(input, event) {
    const rect = this.range.getBoundingClientRect();
    const min = Number(input.min || 0);
    const max = Number(input.max || 100);
    const step = input.step === 'any' ? 0 : Number(input.step || 1);
    const ratio = this.isVerticalRange()
      ? Math.max(0, Math.min(1, (rect.bottom - event.clientY) / rect.height))
      : Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
    let value = min + ratio * (max - min);
    if (step > 0) value = min + Math.round((value - min) / step) * step;
    return Math.max(min, Math.min(max, value));
  }

  handleRangePointerDown(event) {
    if (this.inputs.length !== 2 || this.disabled) return;
    const [lower, upper] = this.inputs;
    if (lower.valueAsNumber !== upper.valueAsNumber) return;
    const enabledInputs = this.inputs.filter((input) => !input.disabled);
    if (enabledInputs.length === 0) return;

    event.preventDefault();
    this.pointerDrag = {
      pointerId: event.pointerId,
      startPosition: this.pointerPosition(event),
      enabledInputs,
      activeInput: null,
    };
    this.range.setPointerCapture?.(event.pointerId);
  }

  handleRangePointerMove(event) {
    const drag = this.pointerDrag;
    if (!drag || drag.pointerId !== event.pointerId) return;
    event.preventDefault();

    if (!drag.activeInput) {
      const position = this.pointerPosition(event);
      if (position === drag.startPosition) return;
      const directionalInput = position < drag.startPosition ? this.inputs[0] : this.inputs[1];
      drag.activeInput = directionalInput.disabled ? drag.enabledInputs[0] : directionalInput;
      drag.activeInput.focus();
    }

    drag.activeInput.value = this.valueFromPointer(drag.activeInput, event);
    drag.activeInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  handleRangePointerEnd(event) {
    const drag = this.pointerDrag;
    if (!drag || drag.pointerId !== event.pointerId) return;
    event.preventDefault();
    if (drag.activeInput) drag.activeInput.dispatchEvent(new Event('change', { bubbles: true }));
    this.range.releasePointerCapture?.(event.pointerId);
    this.pointerDrag = null;
  }

  /* ═══ CHANGE EVENT HANDLER ═══ */
  handleChange(event) {
    this.dispatchEvent(
      new CustomEvent('ren-slider-change', {
        detail: { value: this.value },
        bubbles: true,
        composed: true,
      })
    );
  }

  /* ═══ TRANSFER VARIANT CLASSES TO TRACK ═══ */
  transferVariantClasses() {
    if (!this.input) return;

    const trackContainer = this.input.parentElement || this.input;
    const variants = ['sm', 'lg', 'success', 'warning', 'danger', 'vertical'];

    variants.forEach((variant) => {
      if (this.classList.contains(`ren-slider-${variant}`)) {
        trackContainer.classList.add(`ren-slider-${variant}`);
      }
    });
  }

  /* ═══ GETTERS AND SETTERS ═══ */
  get value() {
    if (!this.input) return null;
    const values = this.inputs.map((input) => input.valueAsNumber);
    return values.length === 2 ? values : values[0];
  }

  set value(val) {
    if (!this.input) return;
    const values = Array.isArray(val) ? [...val] : [val];
    if (this.inputs.length === 2 && values.length >= 2) {
      values.splice(0, 2, ...values.slice(0, 2).map(Number).sort((a, b) => a - b));
    }
    this.inputs.forEach((input, index) => {
      if (values[index] !== undefined) input.value = values[index];
    });
    this.updateValue();
    this.updateValueDisplay();
  }

  get min() {
    return this.input ? parseFloat(this.input.min) : null;
  }

  set min(val) {
    if (this.input) {
      this.inputs.forEach((input) => input.min = val);
      this.updateValue();
    }
  }

  get max() {
    return this.input ? parseFloat(this.input.max) : null;
  }

  set max(val) {
    if (this.input) {
      this.inputs.forEach((input) => input.max = val);
      this.updateValue();
    }
  }

  get disabled() {
    return this.input ? this.inputs.every((input) => input.disabled) : false;
  }

  set disabled(val) {
    if (this.input) {
      this.inputs.forEach((input) => input.disabled = val);
    }
  }
}

/* ═══ REGISTER COMPONENT ═══ */
if (!customElements.get('ren-slider')) {
  customElements.define('ren-slider', RenSlider);
}

/* ═══ TABS CONTAINER ═══ */
.ren-tabs {
  container-type: inline-size;
  container-name: ren-tabs;
  display: flex;
  flex-direction: column;
  width: 100%;
}

/* ═══ TAB LIST ═══ */
.ren-tab-list {
  display: flex;
  flex-direction: row;
  gap: var(--space-2);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/* Smooth scrolling for horizontal tabs */
.ren-tab-list {
  scroll-behavior: smooth;
}

/* ═══ TAB ITEM (UNDERLINE VARIANT - DEFAULT) ═══ */
.ren-tab {
  position: relative;
  padding: var(--space-2) var(--space-4);
  font-size: var(--label-md-size);
  font-weight: var(--label-md-weight);
  line-height: 1;
  color: var(--color-text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  min-height: var(--size-lg);
  display: flex;
  align-items: center;
  white-space: nowrap;
  user-select: none;
  transition: var(--transition-tactile);
}

/* Active tab */
.ren-tab[aria-selected="true"] {
  color: var(--color-text);
  border-bottom-color: var(--color-accent);
  font-weight: var(--label-lg-weight);
}

/* Tab hover state */
.ren-tab:hover:not([aria-disabled="true"]):not(:disabled) {
  color: var(--color-text);
  background-color: var(--color-fill);
}

/* Tab focus ring */
.ren-tab:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: -2px;
  border-radius: var(--radius-sm);
}

/* Disabled tab */
.ren-tab:disabled,
.ren-tab[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
  color: var(--color-text-muted);
}

.ren-tab:disabled:hover,
.ren-tab[aria-disabled="true"]:hover {
  background-color: transparent;
}

/* ═══ TAB PANELS ═══ */
.ren-tab-panel {
  padding-block: var(--space-4);
}

.ren-tab-panel[hidden] {
  display: none;
}

/* Panel focus ring */
.ren-tab-panel:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: var(--radius-md);
}

/* ═══ VARIANT: PILLS ═══ */
.ren-tab-list-pills {
  border-bottom: none;
  gap: var(--space-1);
}

.ren-tab-list-pills .ren-tab {
  border-bottom: none;
  border-radius: var(--radius-md);
  background-color: transparent;
  padding: var(--space-2) var(--space-3);
}

.ren-tab-list-pills .ren-tab[aria-selected="true"] {
  background-color: var(--color-fill);
  border-bottom-color: transparent;
  font-weight: var(--label-lg-weight);
}

.ren-tab-list-pills .ren-tab:hover:not([aria-disabled="true"]):not(:disabled) {
  background-color: var(--color-fill-hover);
}

/* ═══ VARIANT: UNDERLINE (DEFAULT) ═══ */
.ren-tab-list-underline {
  border-bottom: 1px solid var(--color-border);
  gap: var(--space-2);
}

.ren-tab-list-underline .ren-tab {
  border-bottom: 2px solid transparent;
}

.ren-tab-list-underline .ren-tab[aria-selected="true"] {
  border-bottom-color: var(--color-accent);
}

/* ═══ VARIANT: ENCLOSED ═══ */
.ren-tab-list-enclosed {
  border-bottom: none;
  gap: var(--space-2);
}

.ren-tab-list-enclosed .ren-tab {
  border: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  background-color: var(--color-fill);
  padding: var(--space-3) var(--space-4);
}

.ren-tab-list-enclosed .ren-tab[aria-selected="true"] {
  border-color: var(--color-border);
  border-bottom-color: var(--color-surface);
  background-color: var(--color-surface);
  color: var(--color-text);
  position: relative;
  z-index: 1;
}

.ren-tab-list-enclosed .ren-tab[aria-selected="true"]::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: -1px;
  right: -1px;
  height: 1px;
  background-color: var(--color-surface);
}

.ren-tab-list-enclosed .ren-tab:hover:not([aria-disabled="true"]):not(:disabled) {
  background-color: var(--color-fill-hover);
}

/* ═══ COMPACT LAYOUT (Container Query) ═══ */
@container ren-tabs (max-width: 480px) {
  .ren-tab-list {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    /* Add scrollbar styling for better UX */
    scrollbar-width: thin;
    scrollbar-color: var(--color-border) transparent;
  }

  .ren-tab-list::-webkit-scrollbar {
    height: 4px;
  }

  .ren-tab-list::-webkit-scrollbar-track {
    background: transparent;
  }

  .ren-tab-list::-webkit-scrollbar-thumb {
    background-color: var(--color-border);
    border-radius: 2px;
  }
}

/* ═══ REDUCED MOTION ═══ */
@media (prefers-reduced-motion: reduce) {
  .ren-tab {
    transition: none;
  }
}
/* Appearance API bridge */
.ren-tabs {
  min-block-size: var(--ren-tabs-height, var(--size-lg));
  font-size: var(--ren-tabs-font-size, var(--label-size));
  font-weight: var(--ren-tabs-font-weight, var(--label-weight));
  color: var(--ren-tabs-color, var(--color-text-muted));
  border-color: var(--ren-tabs-border-color, var(--color-border));
  gap: var(--ren-tabs-gap, 0);
  transition-duration: var(--ren-tabs-duration, var(--duration-fast));
  transition-timing-function: var(--ren-tabs-easing, var(--ease-out));
}
.ren-tabs [aria-selected="true"], .ren-tabs [data-state="active"] { color: var(--ren-tabs-active-color, var(--color-text)); }
.ren-tabs [data-indicator], .ren-tabs-indicator { background: var(--ren-tabs-indicator-color, var(--color-accent)); }

/**
 * RenDS — <ren-tabs> Web Component
 * ==================================
 * Accessible tabbed interface with keyboard navigation.
 * Implements ARIA tablist pattern with manual or automatic activation.
 *
 * Uses Light DOM — no Shadow DOM.
 * Works with semantic HTML or custom tab markup.
 *
 * Attributes:
 *   activation:    'manual' (default) | 'automatic'
 *                  - manual: arrow keys move focus, Enter/Space selects
 *                  - automatic: arrow keys immediately select tabs
 *   default-value: index or tab ID to select initially
 *   orientation:   'horizontal' (default) | 'vertical'
 *
 * Markup:
 *   <ren-tabs>
 *     <div role="tablist" class="ren-tab-list">
 *       <button role="tab" class="ren-tab">Tab 1</button>
 *       <button role="tab" class="ren-tab">Tab 2</button>
 *     </div>
 *     <div role="tabpanel" class="ren-tab-panel">
 *       Panel 1 content
 *     </div>
 *     <div role="tabpanel" class="ren-tab-panel">
 *       Panel 2 content
 *     </div>
 *   </ren-tabs>
 *
 * Events:
 *   ren-tab-change: Dispatched when a tab is selected
 *   - detail: { tab, panel, index, id }
 */

import { createKeyboardNav } from '../../../utils/keyboard-nav.js';
import { autoId } from '../../../utils/id-generator.js';

export class RenTabs extends HTMLElement {
  static get observedAttributes() {
    return ['activation', 'orientation', 'default-value'];
  }

  constructor() {
    super();
    this._nav = null;
    this._tabList = null;
    this._tabs = [];
    this._panels = [];
    this._selectedIndex = -1;
  }

  /**
   * Lifecycle: Element inserted into DOM
   */
  connectedCallback() {
    this._initialize();
  }

  /**
   * Lifecycle: Element removed from DOM
   */
  disconnectedCallback() {
    if (this._nav) {
      this._nav.detach();
      this._nav = null;
    }
  }

  /**
   * Lifecycle: Observed attribute changed
   */
  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'default-value' && this.isConnected) {
      this._selectTabByValue(newValue);
    }
  }

  /* ═══ INITIALIZATION ═══ */

  /**
   * Initialize the tabs component
   * @private
   */
  _initialize() {
    // Find tablist container
    this._tabList = this.querySelector('[role="tablist"]') || this.querySelector('.ren-tab-list');
    if (!this._tabList) {
      console.warn('RenTabs: No tablist found');
      return;
    }

    // Collect tabs and panels
    this._tabs = Array.from(this.querySelectorAll('[role="tab"], .ren-tab'));
    this._panels = Array.from(this.querySelectorAll('[role="tabpanel"], .ren-tab-panel'));

    if (this._tabs.length === 0) {
      console.warn('RenTabs: No tabs found');
      return;
    }

    // Ensure all elements have proper ARIA roles
    this._tabList.setAttribute('role', 'tablist');
    this._tabs.forEach((tab) => {
      if (!tab.hasAttribute('role')) {
        tab.setAttribute('role', 'tab');
      }
    });
    this._panels.forEach((panel) => {
      if (!panel.hasAttribute('role')) {
        panel.setAttribute('role', 'tabpanel');
      }
    });

    // Wire up ARIA relationships
    this._wireAria();

    // Set up keyboard navigation
    this._setupKeyboardNav();

    // Select initial tab
    const defaultValue = this.getAttribute('default-value');
    if (defaultValue !== null) {
      this._selectTabByValue(defaultValue);
    } else {
      // Select first tab by default
      this._selectTab(0);
    }

    // Listen for clicks on tabs
    this._tabList.addEventListener('click', this._handleTabClick.bind(this));
  }

  /**
   * Wire up ARIA attributes between tabs and panels
   * @private
   */
  _wireAria() {
    this._tabs.forEach((tab, index) => {
      // Ensure tab has an ID
      autoId(tab, `tab-${index}`);

      // Find corresponding panel
      const panel = this._panels[index];
      if (panel) {
        // Ensure panel has an ID
        autoId(panel, `tabpanel-${index}`);

        // Wire aria-controls: tab controls panel
        tab.setAttribute('aria-controls', panel.id);

        // Wire aria-labelledby: panel is labeled by tab
        panel.setAttribute('aria-labelledby', tab.id);
      }

      // Initialize aria-selected state
      tab.setAttribute('aria-selected', index === this._selectedIndex ? 'true' : 'false');
    });
  }

  /**
   * Set up keyboard navigation using createKeyboardNav
   * @private
   */
  _setupKeyboardNav() {
    const activation = this.getAttribute('activation') || 'manual';
    const orientation = this.getAttribute('orientation') || 'horizontal';

    this._nav = createKeyboardNav(this._tabList, {
      selector: '[role="tab"]',
      orientation,
      loop: true,
      typeahead: false,
      focusOnHover: false,
      onActivate: (tab, index) => {
        // Arrow key navigation
        if (activation === 'automatic') {
          // Automatic: immediately select the tab
          this._selectTab(index);
        }
        // Manual: just move focus, don't select
        // (User must press Enter/Space to select)
      },
      onSelect: (tab, index) => {
        // Enter/Space pressed on focused tab
        this._selectTab(index);
      },
    });

    this._nav.attach();
  }

  /**
   * Handle direct click on a tab
   * @private
   */
  _handleTabClick(event) {
    const tab = event.target.closest('[role="tab"]');
    if (!tab) return;

    const index = this._tabs.indexOf(tab);
    if (index !== -1) {
      this._selectTab(index);
      // Ensure focus is on the clicked tab
      tab.focus();
    }
  }

  /* ═══ TAB SELECTION ═══ */

  /**
   * Select a tab by index
   * @param {number} index - Tab index
   * @private
   */
  _selectTab(index) {
    if (index < 0 || index >= this._tabs.length) {
      return;
    }

    // Deselect all tabs and hide all panels
    this._tabs.forEach((tab, i) => {
      const isSelected = i === index;
      tab.setAttribute('aria-selected', isSelected ? 'true' : 'false');
      tab.setAttribute('data-state', isSelected ? 'active' : 'inactive');
      if (this._panels[i]) {
        this._panels[i].toggleAttribute('hidden', !isSelected);
      }
    });

    this._selectedIndex = index;

    // Dispatch custom event
    const tab = this._tabs[index];
    const panel = this._panels[index];
    this.dispatchEvent(
      new CustomEvent('ren-tab-change', {
        detail: {
          tab,
          panel,
          index,
          id: tab.id,
        },
        bubbles: true,
        composed: true,
      })
    );
  }

  /**
   * Select a tab by ID or index value
   * @param {string|number} value - Tab ID or index string
   * @private
   */
  _selectTabByValue(value) {
    // Try parsing as index first
    const indexValue = parseInt(value, 10);
    if (!isNaN(indexValue) && indexValue >= 0 && indexValue < this._tabs.length) {
      this._selectTab(indexValue);
      return;
    }

    // Try finding by ID
    const tab = this._tabs.find((t) => t.id === value);
    if (tab) {
      const index = this._tabs.indexOf(tab);
      this._selectTab(index);
    }
  }

  /* ═══ PUBLIC API ═══ */

  /**
   * Get the currently selected tab index
   * @returns {number}
   */
  get selectedIndex() {
    return this._selectedIndex;
  }

  /**
   * Get the currently selected tab element
   * @returns {HTMLElement|null}
   */
  get selectedTab() {
    return this._selectedIndex >= 0 ? this._tabs[this._selectedIndex] : null;
  }

  /**
   * Get the currently selected panel element
   * @returns {HTMLElement|null}
   */
  get selectedPanel() {
    return this._selectedIndex >= 0 ? this._panels[this._selectedIndex] : null;
  }

  /**
   * Programmatically select a tab by index
   * @param {number} index
   */
  selectTabByIndex(index) {
    this._selectTab(index);
  }

  /**
   * Programmatically select a tab by ID
   * @param {string} id
   */
  selectTabById(id) {
    const index = this._tabs.findIndex((t) => t.id === id);
    if (index !== -1) {
      this._selectTab(index);
    }
  }

  /**
   * Get all tabs
   * @returns {HTMLElement[]}
   */
  get tabs() {
    return [...this._tabs];
  }

  /**
   * Get all panels
   * @returns {HTMLElement[]}
   */
  get panels() {
    return [...this._panels];
  }
}

// Register the component
if (!customElements.get('ren-tabs')) {
  customElements.define('ren-tabs', RenTabs);
}

/**
 * RenDS — Toast Notification System CSS
 * =====================================
 * Styles for notification toasts with animations,
 * positioning, variants, and responsive behavior.
 */

/* ═══ VIEWPORT CONTAINER ═══ */
.ren-toast-viewport {
  position: fixed;
  z-index: var(--z-toast, 9999);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  max-height: 100dvh;
  overflow: hidden;
  pointer-events: none;
  max-width: min(420px, calc(100vw - 2rem));
}

/* Position variants */
.ren-toast-viewport[data-position="top-right"] {
  top: var(--space-4);
  right: var(--space-4);
  flex-direction: column;
}

.ren-toast-viewport[data-position="top-left"] {
  top: var(--space-4);
  left: var(--space-4);
  flex-direction: column;
}

.ren-toast-viewport[data-position="top-center"] {
  top: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  flex-direction: column;
}

.ren-toast-viewport[data-position="bottom-right"] {
  bottom: var(--space-4);
  right: var(--space-4);
  flex-direction: column-reverse;
}

.ren-toast-viewport[data-position="bottom-left"] {
  bottom: var(--space-4);
  left: var(--space-4);
  flex-direction: column-reverse;
}

.ren-toast-viewport[data-position="bottom-center"] {
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  flex-direction: column-reverse;
}

/* ═══ TOAST CONTAINER ═══ */
.ren-toast {
  pointer-events: auto;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: var(--space-3) var(--space-4);
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
  min-width: 20rem;
  max-width: 100%;
  position: relative;
  overflow: hidden;
  /* Enter + exit use semantic tokens so global motion tuning cascades here. */
  animation: ren-toast-fade-in var(--duration-enter) var(--ease-enter);
}

.ren-toast[data-closing] {
  animation: ren-toast-fade-out var(--duration-exit) var(--ease-exit);
  opacity: 0;
}

/* Slide-in animations by position */
.ren-toast-viewport[data-position="top-right"] .ren-toast,
.ren-toast-viewport[data-position="bottom-right"] .ren-toast {
  animation: ren-toast-slide-in-right var(--duration-enter) var(--ease-enter);
}

.ren-toast-viewport[data-position="top-right"] .ren-toast[data-closing],
.ren-toast-viewport[data-position="bottom-right"] .ren-toast[data-closing] {
  animation: ren-toast-slide-out-right var(--duration-exit) var(--ease-exit);
}

.ren-toast-viewport[data-position="top-left"] .ren-toast,
.ren-toast-viewport[data-position="bottom-left"] .ren-toast {
  animation: ren-toast-slide-in-left var(--duration-enter) var(--ease-enter);
}

.ren-toast-viewport[data-position="top-left"] .ren-toast[data-closing],
.ren-toast-viewport[data-position="bottom-left"] .ren-toast[data-closing] {
  animation: ren-toast-slide-out-left var(--duration-exit) var(--ease-exit);
}

.ren-toast-viewport[data-position="top-center"] .ren-toast,
.ren-toast-viewport[data-position="bottom-center"] .ren-toast {
  animation: ren-toast-fade-in var(--duration-enter) var(--ease-enter);
}

/* ═══ TOAST CONTENT STRUCTURE ═══ */
.ren-toast-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
}

/* Body wraps title + description + actions */
.ren-toast-body {
  flex: 1;
  min-width: 0;
}

.ren-toast-title {
  font-weight: var(--font-weight-semibold, 600);
  font-size: var(--text-sm);
  line-height: var(--leading-5);
  color: var(--color-text);
  margin: 0;
}

.ren-toast-description {
  font-size: var(--text-xs);
  line-height: 1.5;
  color: var(--color-text-muted);
  margin: var(--space-1) 0 0;
}

.ren-toast-actions {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-2);
  flex-wrap: wrap;
}

/* The action button itself (the docs name it .ren-toast-action; we layer it
   on top of the standard .ren-btn variants for consistent styling). */
.ren-toast-action {
  /* Inherits its visual from .ren-btn ren-btn-ghost ren-btn-sm — this rule
     is just a hook for consumers who want to override per-toast. */
}

.ren-toast-close {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  cursor: pointer;
  padding: var(--space-1);
  font-size: 18px;
  line-height: 1;
  /* Tactile (hover/focus/press) — uses shared semantic preset */
  transition: var(--transition-tactile);
}

.ren-toast-close:hover {
  background-color: var(--color-surface-hover);
  color: var(--color-text);
}

.ren-toast-close:active {
  background-color: var(--color-surface-active);
}

/* ═══ TOAST VARIANTS ═══ */
/* Success */
.ren-toast-success {
  background: color-mix(in srgb, var(--color-success-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-success .ren-toast-icon {
  color: var(--color-success);
}

/* Error / Danger */
.ren-toast-error,
.ren-toast-danger {
  background: color-mix(in srgb, var(--color-danger-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-error .ren-toast-icon,
.ren-toast-danger .ren-toast-icon {
  color: var(--color-danger);
}

/* Warning */
.ren-toast-warning {
  background: color-mix(in srgb, var(--color-warning-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-warning .ren-toast-icon {
  color: var(--color-warning);
}

/* Info */
.ren-toast-info {
  background: color-mix(in srgb, var(--color-info-subtle) 65%, var(--color-surface-raised));
}

.ren-toast-info .ren-toast-icon {
  color: var(--color-info);
}

/* Loading */
.ren-toast-loading .ren-toast-icon {
  animation: ren-spinner-rotate 0.8s linear infinite;
}

/* ═══ PROGRESS BAR ═══ */
.ren-toast-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width linear;
}

/* ═══ SWIPE STATE ═══ */
.ren-toast[data-swiping] {
  transition: none;
}

/* ═══ ANIMATIONS ═══ */
@keyframes ren-toast-slide-in-right {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes ren-toast-slide-in-left {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes ren-toast-slide-out-right {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(100%);
    opacity: 0;
  }
}

@keyframes ren-toast-slide-out-left {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}

@keyframes ren-toast-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes ren-toast-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes ren-spinner-rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* ═══ REDUCED MOTION ═══
   Belt-and-suspenders: semantic --duration-* already collapse
   to 0ms under reduced-motion (see tokens/semantic/motion.css),
   so the animations above become instant. We keep this block
   to force a plain fade (no slide) as an Apple-HIG alternative,
   and to stop the loading spinner. */
@media (prefers-reduced-motion: reduce) {
  .ren-toast,
  .ren-toast[data-closing],
  .ren-toast-viewport[data-position="top-right"] .ren-toast,
  .ren-toast-viewport[data-position="bottom-right"] .ren-toast,
  .ren-toast-viewport[data-position="top-left"] .ren-toast,
  .ren-toast-viewport[data-position="bottom-left"] .ren-toast,
  .ren-toast-viewport[data-position="top-center"] .ren-toast,
  .ren-toast-viewport[data-position="bottom-center"] .ren-toast {
    animation: ren-toast-fade-in var(--duration-micro) linear !important;
  }

  .ren-toast[data-closing] {
    animation: ren-toast-fade-out var(--duration-micro) linear !important;
  }

  .ren-toast-loading .ren-toast-icon {
    animation: none;
    opacity: 0.6;
  }
}

/* ═══ RESPONSIVE ═══ */
@media (max-width: 640px) {
  .ren-toast-viewport {
    max-width: calc(100vw - 1rem);
    bottom: var(--space-3);
    left: var(--space-2);
    right: var(--space-2);
    width: auto;
  }

  .ren-toast-viewport[data-position="top-right"],
  .ren-toast-viewport[data-position="top-left"],
  .ren-toast-viewport[data-position="top-center"] {
    bottom: auto;
    left: var(--space-2);
    right: var(--space-2);
    width: auto;
    transform: none;
  }

  .ren-toast-viewport[data-position="bottom-right"],
  .ren-toast-viewport[data-position="bottom-left"],
  .ren-toast-viewport[data-position="bottom-center"] {
    bottom: var(--space-3);
    left: var(--space-2);
    right: var(--space-2);
    width: auto;
    transform: none;
  }

  .ren-toast {
    min-width: unset;
    width: 100%;
  }
}
/* Appearance API bridge */
.ren-toast { inline-size: var(--ren-toast-width, 360px); padding: var(--ren-toast-padding, var(--space-4)); border-radius: var(--ren-toast-radius, var(--radius-lg)); background: var(--ren-toast-bg, var(--color-surface-raised)); border-color: var(--ren-toast-border, var(--color-border)); box-shadow: var(--ren-toast-shadow, var(--shadow-lg)); gap: var(--ren-toast-gap, var(--space-3)); animation-duration: var(--ren-toast-anim-duration, var(--duration-normal)); animation-timing-function: var(--ren-toast-easing, var(--ease-out)); }

@media (any-pointer: coarse), (pointer: coarse) {
  .ren-toast-close {
    min-inline-size: var(--touch-min);
    min-block-size: var(--touch-min);
  }
}

/**
 * RenDS — Toast Notification System
 * ==================================
 * Transient notifications anchored to a corner of the viewport.
 *
 * Light DOM only. The viewport is a plain element with class
 * `.ren-toast-viewport` (or the convenience custom element
 * `<ren-toast-viewport>`). Toasts are plain `.ren-toast` divs
 * appended to it.
 *
 * Public API (also available as `window.toast`):
 *   toast.success(title, options?)
 *   toast.info(title, options?)
 *   toast.warning(title, options?)
 *   toast.danger(title, options?)
 *   toast.show(options)            — { title, description, status, duration, action }
 *   toast.dismiss(id)
 *   toast.dismissAll()
 *   toast.promise(promise, { loading, success, error })
 *
 * Options:
 *   title        — required string
 *   description  — optional secondary line
 *   status       — "success" | "info" | "warning" | "danger" | "loading"
 *   duration     — auto-dismiss ms (0 = persistent, default 4000 / 8000 for danger)
 *   dismissible  — show close button (default true)
 *   action       — { label, onClick } inline button
 */

import { announceAssertive, announcePolite } from '../../../utils/live-region.js';

/* ─── Defaults ─── */

const DEFAULT_DURATIONS = {
  success: 4000,
  info: 4000,
  warning: 5000,
  danger: 8000,
  loading: 0, // persistent
};

const ICONS = {
  success: '✓',
  info: 'ℹ',
  warning: '⚠',
  danger: '✕',
  loading: '⟳',
};

const VALID_POSITIONS = new Set([
  'top-right',
  'top-left',
  'top-center',
  'bottom-right',
  'bottom-left',
  'bottom-center',
]);

/* ─── Custom element (convenience) ─── */

export class RenToastViewport extends HTMLElement {
  connectedCallback() {
    this._listenerController?.abort();
    this._listenerController = new AbortController();
    const { signal } = this._listenerController;

    this.classList.add('ren-toast-viewport');
    if (!this.hasAttribute('data-position')) {
      this.setAttribute('data-position', 'bottom-right');
    }
    if (!VALID_POSITIONS.has(this.getAttribute('data-position'))) {
      this.setAttribute('data-position', 'bottom-right');
    }
    if (!this.hasAttribute('aria-label')) {
      this.setAttribute('aria-label', 'Notifications');
    }
    if (!this.hasAttribute('role')) this.setAttribute('role', 'region');

    // Pause timers on hover or keyboard focus
    this.addEventListener('mouseenter', () => pauseTimersFor(this), { signal });
    this.addEventListener('mouseleave', () => resumeTimersFor(this), { signal });
    this.addEventListener('focusin', () => pauseTimersFor(this), { signal });
    this.addEventListener('focusout', (e) => {
      if (!this.contains(e.relatedTarget)) resumeTimersFor(this);
    }, { signal });
  }

  disconnectedCallback() {
    this._listenerController?.abort();
    this._listenerController = null;
    resumeTimersFor(this);
  }
}

if (!customElements.get('ren-toast-viewport')) {
  customElements.define('ren-toast-viewport', RenToastViewport);
}

/* ─── Per-viewport timer book-keeping ─── */

const timerStore = new WeakMap(); // viewport → { timers: Map<id, {timerId, remaining, startedAt}>, paused: bool }

function getStore(viewport) {
  let store = timerStore.get(viewport);
  if (!store) {
    store = { timers: new Map(), paused: false };
    timerStore.set(viewport, store);
  }
  return store;
}

function pauseTimersFor(viewport) {
  const store = getStore(viewport);
  if (store.paused) return;
  store.paused = true;
  for (const [id, info] of store.timers.entries()) {
    if (info.timerId == null) continue;
    clearTimeout(info.timerId);
    info.timerId = null;
    if (info.startedAt && info.remaining) {
      info.remaining = Math.max(0, info.remaining - (Date.now() - info.startedAt));
    }
    // Pause progress bar (freeze its current width)
    const toastEl = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
    if (toastEl) {
      const progress = toastEl.querySelector('.ren-toast-progress');
      if (progress) {
        const width = getComputedStyle(progress).width;
        progress.style.transition = 'none';
        progress.style.width = width;
      }
    }
  }
}

function resumeTimersFor(viewport) {
  const store = getStore(viewport);
  if (!store.paused) return;
  store.paused = false;
  for (const [id, info] of store.timers.entries()) {
    if (info.remaining > 0) {
      info.startedAt = Date.now();
      info.timerId = setTimeout(() => dismissToast(viewport, id), info.remaining);
      // Resume progress bar
      const toastEl = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
      if (toastEl) {
        const progress = toastEl.querySelector('.ren-toast-progress');
        if (progress) {
          // Force reflow then animate to 0
          progress.style.transition = `width ${info.remaining}ms linear`;
          requestAnimationFrame(() => {
            progress.style.width = '0%';
          });
        }
      }
    }
  }
}

/* ─── Viewport resolution ─── */

let _autoViewport = null;

function resolveViewport(preferredId) {
  if (preferredId) {
    const v = document.getElementById(preferredId);
    if (v) return v;
  }
  if (_autoViewport && document.body.contains(_autoViewport)) {
    return _autoViewport;
  }
  // Look for any existing viewport in the page
  const existing = document.querySelector('.ren-toast-viewport, ren-toast-viewport');
  if (existing) {
    _autoViewport = existing;
    return existing;
  }
  // Auto-create
  _autoViewport = document.createElement('ren-toast-viewport');
  _autoViewport.setAttribute('data-position', 'bottom-right');
  document.body.appendChild(_autoViewport);
  return _autoViewport;
}

/* ─── Toast construction ─── */

function generateId() {
  return `toast-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function normalize(input, statusOverride) {
  const opts = typeof input === 'string' ? { title: input } : { ...input };
  opts.statusExplicit = statusOverride != null || opts.status != null;
  if (statusOverride) opts.status = statusOverride;
  if (!opts.status) opts.status = 'info';
  opts.durationExplicit = opts.duration != null;
  if (opts.duration == null) opts.duration = DEFAULT_DURATIONS[opts.status] ?? 4000;
  if (opts.dismissible == null) opts.dismissible = true;
  return opts;
}

function buildToast(id, opts) {
  const { title, description, status, duration, dismissible, action } = opts;

  const toast = document.createElement('div');
  toast.className = `ren-toast ren-toast-${status}`;
  toast.setAttribute('data-toast-id', id);
  if (duration > 0) toast.setAttribute('data-duration', String(duration));
  toast.setAttribute('role', status === 'danger' ? 'alert' : 'status');
  toast.setAttribute('tabindex', '0'); // focusable for Esc/F6

  // Icon
  const icon = document.createElement('span');
  icon.className = 'ren-toast-icon';
  icon.setAttribute('aria-hidden', 'true');
  icon.textContent = ICONS[status] ?? ICONS.info;
  toast.appendChild(icon);

  // Body (title + description + action)
  const body = document.createElement('div');
  body.className = 'ren-toast-body';

  if (title) {
    const t = document.createElement('p');
    t.className = 'ren-toast-title';
    t.textContent = title;
    body.appendChild(t);
  }

  if (description) {
    const d = document.createElement('p');
    d.className = 'ren-toast-description';
    d.textContent = description;
    body.appendChild(d);
  }

  if (action && action.label) {
    const actions = document.createElement('div');
    actions.className = 'ren-toast-actions';

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'ren-toast-action ren-btn ren-btn-ghost ren-btn-sm';
    btn.textContent = action.label;
    btn.addEventListener('click', () => {
      try {
        action.onClick?.();
      } finally {
        // Find the host viewport at click time (toast may have moved? unlikely)
        const viewport = toast.closest('.ren-toast-viewport, ren-toast-viewport');
        if (viewport) dismissToast(viewport, id);
      }
    });
    actions.appendChild(btn);
    body.appendChild(actions);
  }

  toast.appendChild(body);

  // Close button
  if (dismissible) {
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'ren-toast-close';
    close.setAttribute('aria-label', 'Dismiss notification');
    close.textContent = '×';
    close.addEventListener('click', () => {
      const viewport = toast.closest('.ren-toast-viewport, ren-toast-viewport');
      if (viewport) dismissToast(viewport, id);
    });
    toast.appendChild(close);
  }

  // Progress bar (auto-dismiss countdown)
  if (duration > 0) {
    const progress = document.createElement('div');
    progress.className = 'ren-toast-progress';
    progress.style.width = '100%';
    progress.style.transition = `width ${duration}ms linear`;
    toast.appendChild(progress);
    requestAnimationFrame(() => {
      progress.style.width = '0%';
    });
  }

  // Esc dismisses when toast itself has focus
  toast.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const viewport = toast.closest('.ren-toast-viewport, ren-toast-viewport');
      if (viewport) dismissToast(viewport, id);
    }
  });

  return toast;
}

/* ─── Show / dismiss ─── */

function showOnViewport(viewport, opts) {
  const id = opts.id || generateId();

  // If a toast with this id exists, replace it
  const existing = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
  if (existing) {
    existing.remove();
    const store = getStore(viewport);
    const t = store.timers.get(id);
    if (t?.timerId) clearTimeout(t.timerId);
    store.timers.delete(id);
  }

  const toast = buildToast(id, opts);
  viewport.appendChild(toast);

  // Resolve the closest effective token scope, including overrides on the
  // generated toast itself. Explicit duration/status options remain
  // authoritative.
  if (!opts.durationExplicit && !opts.statusExplicit) {
    const tokenDuration = getComputedStyle(toast)
      .getPropertyValue('--ren-toast-duration')
      .trim();
    const parsedDuration = parseFloat(tokenDuration);
    if (Number.isFinite(parsedDuration) && parsedDuration >= 0) {
      opts.duration = parsedDuration;
      const progress = toast.querySelector('.ren-toast-progress');
      if (opts.duration > 0) {
        toast.setAttribute('data-duration', String(opts.duration));
        if (progress) progress.style.transition = `width ${opts.duration}ms linear`;
      } else if (progress) {
        progress.remove();
        toast.removeAttribute('data-duration');
      }
    }
  }

  if (!opts.durationExplicit && opts.duration > 0) toast.setAttribute('data-duration', String(opts.duration));

  // Schedule auto-dismiss
  if (opts.duration > 0) {
    const store = getStore(viewport);
    const startedAt = Date.now();
    const timerId = store.paused
      ? null
      : setTimeout(() => dismissToast(viewport, id), opts.duration);
    store.timers.set(id, { timerId, remaining: opts.duration, startedAt });
  }

  // Announce via live region (separate from the toast DOM so SRs don't double-up)
  const announcement = [opts.title, opts.description].filter(Boolean).join('. ');
  if (announcement) {
    if (opts.status === 'danger') announceAssertive(announcement);
    else announcePolite(announcement);
  }

  // Enforce optional max-toasts
  enforceMax(viewport);

  return id;
}

function enforceMax(viewport) {
  const max = parseInt(viewport.getAttribute('data-max'), 10);
  if (!max || isNaN(max)) return;
  const toasts = viewport.querySelectorAll('.ren-toast:not([data-closing])');
  if (toasts.length <= max) return;
  for (let i = 0; i < toasts.length - max; i++) {
    dismissToast(viewport, toasts[i].dataset.toastId);
  }
}

function dismissToast(viewport, id) {
  if (!viewport || !id) return;
  const toast = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
  if (!toast) return;

  const store = getStore(viewport);
  const t = store.timers.get(id);
  if (t?.timerId) clearTimeout(t.timerId);
  store.timers.delete(id);

  toast.setAttribute('data-closing', '');

  // Wait for the exit animation, then remove
  const dur = parseFloat(getComputedStyle(toast).animationDuration) * 1000 || 200;
  setTimeout(() => toast.remove(), dur);
}

/* ─── F6: focus viewport globally ─── */

function setupGlobalKeys() {
  if (window.__renToastF6Wired) return;
  window.__renToastF6Wired = true;
  document.addEventListener('keydown', (e) => {
    if (e.key === 'F6') {
      const viewport = document.querySelector('ren-toast-viewport, .ren-toast-viewport');
      if (!viewport) return;
      const firstToast = viewport.querySelector('.ren-toast');
      if (firstToast) {
        e.preventDefault();
        firstToast.focus();
      }
    }
  });
}

setupGlobalKeys();

/* ─── Public API ─── */

function show(input) {
  const opts = normalize(input);
  const viewport = resolveViewport();
  return showOnViewport(viewport, opts);
}

function variantFn(status) {
  return function (title, options = {}) {
    const opts =
      typeof title === 'string'
        ? { ...options, title }
        : { ...title, ...options };
    return show(normalize(opts, status));
  };
}

export const toast = Object.assign(show, {
  show,
  success: variantFn('success'),
  info: variantFn('info'),
  warning: variantFn('warning'),
  danger: variantFn('danger'),
  // Common alias for users coming from other libs
  error: variantFn('danger'),
  loading: variantFn('loading'),

  dismiss(id) {
    const viewport = resolveViewport();
    dismissToast(viewport, id);
  },

  dismissAll() {
    const viewport = resolveViewport();
    viewport.querySelectorAll('.ren-toast:not([data-closing])').forEach((t) => {
      dismissToast(viewport, t.dataset.toastId);
    });
  },

  update(id, updates) {
    const viewport = resolveViewport();
    const toastEl = viewport.querySelector(`[data-toast-id="${CSS.escape(id)}"]`);
    if (!toastEl) return;
    if (updates.status) {
      toastEl.className = `ren-toast ren-toast-${updates.status}`;
      toastEl.setAttribute('data-toast-id', id);
      toastEl.setAttribute(
        'role',
        updates.status === 'danger' ? 'alert' : 'status'
      );
      const icon = toastEl.querySelector('.ren-toast-icon');
      if (icon) icon.textContent = ICONS[updates.status] ?? ICONS.info;
    }
    if (updates.title !== undefined) {
      const t = toastEl.querySelector('.ren-toast-title');
      if (t) t.textContent = updates.title;
    }
    if (updates.description !== undefined) {
      const d = toastEl.querySelector('.ren-toast-description');
      if (d) d.textContent = updates.description;
    }
  },

  promise(promise, options = {}) {
    const id = generateId();
    const loadingOpts = normalize(options.loading || 'Loading...', 'loading');
    loadingOpts.id = id;
    const viewport = resolveViewport();
    showOnViewport(viewport, loadingOpts);

    return promise
      .then((data) => {
        const successInput =
          typeof options.success === 'function'
            ? options.success(data)
            : options.success;
        const successOpts = normalize(successInput || 'Done', 'success');
        successOpts.id = id;
        showOnViewport(viewport, successOpts);
        return data;
      })
      .catch((err) => {
        const errorInput =
          typeof options.error === 'function' ? options.error(err) : options.error;
        const errorOpts = normalize(errorInput || 'Failed', 'danger');
        errorOpts.id = id;
        showOnViewport(viewport, errorOpts);
        throw err;
      });
  },
});

// Expose globally — the docs show `window.toast.success(...)` as the primary usage.
if (typeof window !== 'undefined') {
  window.toast = toast;
}

