.ren-toolbar { min-block-size: var(--ren-toolbar-height, var(--size-lg)); padding: var(--ren-toolbar-padding, var(--space-1)); border-radius: var(--ren-toolbar-radius, var(--radius-lg)); background: var(--ren-toolbar-bg, var(--color-surface-raised)); border-color: var(--ren-toolbar-border, var(--color-border)); }
.ren-toolbar button, .ren-toolbar [role="button"] { inline-size: var(--ren-toolbar-item-size, var(--size-md)); block-size: var(--ren-toolbar-item-size, var(--size-md)); border-radius: var(--ren-toolbar-item-radius, var(--radius-sm)); }
.ren-toolbar button:hover, .ren-toolbar [role="button"]:hover { background: var(--ren-toolbar-item-hover, var(--color-fill)); }
.ren-toolbar button[aria-pressed="true"], .ren-toolbar [data-state="on"] { background: var(--ren-toolbar-active-bg, var(--color-accent-subtle)); }

/* ============================================
   RenDS — Toolbar Keyboard Navigation
   ============================================
   Implements WAI-ARIA Toolbar pattern:
   - Arrow Left/Right: move between items
   - Home: first item
   - End: last item
   - Tab: exits toolbar

   Usage:
     import { initToolbar } from './ren-toolbar.js';
     initToolbar(document.querySelector('.ren-toolbar'));

   Or auto-init all:
     import { initAllToolbars } from './ren-toolbar.js';
     initAllToolbars();
   ============================================ */

/**
 * @param {HTMLElement} toolbar
 */
const toolbarControllers = new WeakMap();

export function initToolbar(toolbar) {
  if (!toolbar || toolbar.getAttribute('role') !== 'toolbar') return;

  toolbarControllers.get(toolbar)?.abort();
  const controller = new AbortController();
  toolbarControllers.set(toolbar, controller);

  const getItems = () =>
    [...toolbar.querySelectorAll('.ren-toolbar-item:not(:disabled):not([aria-disabled="true"])')];

  const isVertical = toolbar.classList.contains('ren-toolbar-vertical');
  const prevKey = isVertical ? 'ArrowUp' : 'ArrowLeft';
  const nextKey = isVertical ? 'ArrowDown' : 'ArrowRight';

  toolbar.addEventListener('keydown', (e) => {
    const items = getItems();
    const current = items.indexOf(document.activeElement);
    if (current === -1) return;

    let next = -1;

    if (e.key === nextKey) {
      next = (current + 1) % items.length;
    } else if (e.key === prevKey) {
      next = (current - 1 + items.length) % items.length;
    } else if (e.key === 'Home') {
      next = 0;
    } else if (e.key === 'End') {
      next = items.length - 1;
    }

    if (next !== -1) {
      e.preventDefault();
      items.forEach((item) => item.setAttribute('tabindex', '-1'));
      items[next].setAttribute('tabindex', '0');
      items[next].focus();
    }
  }, { signal: controller.signal });
}

/**
 * Auto-init all toolbars in the document.
 */
export function initAllToolbars() {
  document.querySelectorAll('[role="toolbar"]').forEach(initToolbar);
}

/* ═══ ANCHOR POSITIONING & BASE STYLES ═══ */
.ren-tooltip {
  position: absolute;
  background: var(--ren-tooltip-bg, var(--color-text));
  color: var(--ren-tooltip-color, var(--color-text-inverted));
